xpath.script:
(function () {
    var info = odoo.__session_info__ || {};
    var preference = info.color_scheme_preference || 'system';
    if (preference !== 'system') {
        return;
    }
    var scheme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    var cookies = document.cookie.split(';').map(function (c) { return c.trim(); });
    var current = cookies.find(function (c) { return c.indexOf('color_scheme=') === 0; });
    var currentValue = current ? current.split('=')[1] : null;
    if (currentValue !== scheme) {
        document.cookie = 'color_scheme=' + scheme + '; path=/; max-age=' + (60 * 60 * 24 * 365);
        window.location.reload();
    }
})();
